[{"order":1,"type":"heading","text":"Modules and Plugins Architecture in C++: Unreal Engine"},{"order":2,"type":"paragraph","text":"Unreal Engine uses a modular architecture to ensure clean separation of concerns, faster compilation times, and high reusability of code. Understanding Modules and Plugins is essential for scaling large projects and developing engine-level extensions."},{"order":3,"type":"subheading","text":"Understanding Unreal Engine Modules"},{"order":4,"type":"paragraph","text":"A module is a self-contained unit of code in Unreal Engine. Every game or plugin is composed of one or more modules. Each module has its own build file (.Build.cs) and contains a startup and shutdown routine managed by the IModuleInterface."},{"order":5,"type":"code","text":"#include "Modules/ModuleManager.h"

class FMyGameModule : public IModuleInterface
{
public:
    virtual void StartupModule() override;
    virtual void ShutdownModule() override;
};

IMPLEMENT_PRIMARY_GAME_MODULE(FMyGameModule, MyGame, "MyGame");"},{"order":6,"type":"subheading","text":"Creating a Custom Runtime Module"},{"order":7,"type":"bullet_point","text":"Create a new folder named "MyCustomModule" inside your project's "Source" directory."},{"order":8,"type":"bullet_point","text":"Add a C++ source file and header file named "MyCustomModule.h" and "MyCustomModule.cpp"."},{"order":9,"type":"bullet_point","text":"Create a build file named "MyCustomModule.Build.cs" next to your source files."},{"order":10,"type":"code","text":"using UnrealBuildTool;

public class MyCustomModule : ModuleRules
{
    public MyCustomModule(ReadOnlyTargetRules Target) : base(Target)
    {
        PCHUsage = PCHUsageMode.UseExplicitOrSharedPCHs;

        PublicDependencyModuleNames.AddRange(new string[] { "Core", "CoreUObject", "Engine" });
    }
}"},{"order":11,"type":"subheading","text":"Understanding Unreal Engine Plugins"},{"order":12,"type":"paragraph","text":"Plugins bundle modules, content, and configuration files into a single, self-contained package. They can be enabled or disabled per project, making them ideal for creating modular features that can be shared across multiple projects."},{"order":13,"type":"subheading","text":"Structure of a .uplugin Descriptor File"},{"order":14,"type":"code","text":"{
    "FileVersion": 3,
    "Version": 1,
    "VersionName": "1.0",
    "FriendlyName": "Custom Utility Plugin",
    "Description": "A plugin demonstrating modular C++ architecture.",
    "Category": "Utility",
    "CreatedBy": "Developer",
    "Modules": [
        {
            "Name": "CustomUtilityRuntime",
            "Type": "Runtime",
            "LoadingPhase": "Default"
        }
    ]
}"},{"order":15,"type":"subheading","text":"Best Practices for Module and Plugin Design"},{"order":16,"type":"bullet_point","text":"Keep dependencies pointing inward. Gameplay modules should depend on core modules, but core modules should never depend on gameplay modules."},{"order":17,"type":"bullet_point","text":"Expose minimal public headers in your Public directory to reduce global include dependencies and speed up incremental compilation."},{"order":18,"type":"bullet_point","text":"Use Editor-only modules for tools, Slate panels, and custom details view customizations to keep them out of shipping builds."}]
